var bytes = System.IO.File.ReadAllBytes(UnityEngine.Application.dataPath + "/GameRes/GameConfigs.pb/SystemUnlockInfo.pb.bytes");
var table = Tbl.SystemUnlockInfoTable.Parser.ParseFrom(bytes);
Tbl.SystemUnlockInfo activity = null;
foreach (var row in table.Info) if (row.Name == "活动") activity = row;
if (activity == null) throw new System.Exception("Activity config row missing");
var systemId = Farm.Features.SystemUnlock.SystemUnlockIds.Activity;
var hiddenBefore = Farm.Features.SystemUnlock.SystemUnlockRules.ShouldHideButton(systemId, true, activity.HideButton, true, false, false);
var hiddenAfter = Farm.Features.SystemUnlock.SystemUnlockRules.ShouldHideButton(systemId, true, activity.HideButton, true, true, false);
var entries = Farm.Features.MainUI.MainTopEntries.Build();
var bindings = new System.Collections.Generic.Dictionary<string, uint>();
foreach (var entry in entries) if (entry.FguiName == "ActivityBtn" || entry.FguiName == "GiftBtn") bindings.Add(entry.FguiName, entry.SystemId);
if (systemId != activity.Id || !hiddenBefore || hiddenAfter || bindings.Count != 2 || bindings["ActivityBtn"] != activity.Id || bindings["GiftBtn"] != activity.Id) throw new System.Exception("Activity entry regression failed");
return new { activityConfigId=activity.Id, compiledActivityId=systemId, hiddenBeforeUnlock=hiddenBefore, hiddenAfterUnlock=hiddenAfter, entryBindings=bindings, isPlaying=UnityEngine.Application.isPlaying, dataPath=UnityEngine.Application.dataPath };
